INSERT INTO public.quiz_question (created_at, quiz_id, question_id) VALUES
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_2_62'),
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_2_63'),
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_2_64'),
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_2_65'),
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_2_66'),
  (NOW(), 'quiz_domain19_4', 'q_19_m_19_1_70'),
