INSERT INTO public.quiz_question (created_at, quiz_id, question_id) VALUES
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_26'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_27'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_28'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_29'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_30'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_31'),
  (NOW(), 'quiz_domain20_4', 'q_20_m_20_2_32'),
